import "dns-utils"
import "errors"
import "storage"

contract RootDns {
    author: "The Tolk Team"
    version: "1.0.0"
    description: "Root DNS resolver. Entry point for TON DNS resolution"
    storage: RootDnsStorage
}

fun getPrefixLengthByDomain(domainLength: int, startsWithZeroByte: bool): int {
    return (domainLength - 1) * BYTE_SIZE + (startsWithZeroByte ? BYTE_SIZE : 0);
}

fun onInternalMessage(_in: InMessage) {
    // do nothing
}

get fun dnsresolve(subdomain: slice, _category: int): DnsResolveResponse {
    assert (subdomain.remainingBitsCount() % BYTE_SIZE == 0) throw ERROR_DNS_INVALID_SUBDOMAIN_BITS;

    val startsWithZeroByte = subdomain.preloadInt(BYTE_SIZE) == 0;
    val subdomainLengthInBits = subdomain.remainingBitsCount();

    // "." is resolved, without dns record
    if (startsWithZeroByte && subdomainLengthInBits == BYTE_SIZE) {
        return { resolvedPrefixLengthBits: BYTE_SIZE, resolvedRecord: null };
    }

    if (startsWithZeroByte) {
        subdomain.skipBits(BYTE_SIZE);
    }

    val rootStorage = lazy RootDnsStorage.fromCell(contract.getData());

    val tonWwwDomain = beginCell()
        .storeSlice("ton".literalSlice())
        .storeUint(0, BYTE_SIZE)
        .storeSlice("www".literalSlice())
        .storeUint(0, BYTE_SIZE)
        .toSlice();

    if (subdomainLengthInBits >= TON_WWW_DOMAIN_SIZE * BYTE_SIZE) {
        if (subdomain.preloadBits(TON_WWW_DOMAIN_SIZE * BYTE_SIZE).bitsEqual(tonWwwDomain)) {
            return {
                resolvedPrefixLengthBits: getPrefixLengthByDomain(
                    TON_WWW_DOMAIN_SIZE,
                    startsWithZeroByte,
                ),
                resolvedRecord: rootStorage.tonWwwAddress.toNextResolver(),
            };
        }
    }

    val tonDomain = beginCell().storeSlice("ton".literalSlice()).storeUint(0, BYTE_SIZE).toSlice();

    if (subdomainLengthInBits >= TON_DOMAIN_SIZE * BYTE_SIZE) {
        if (subdomain.preloadBits(TON_DOMAIN_SIZE * BYTE_SIZE).bitsEqual(tonDomain)) {
            return {
                resolvedPrefixLengthBits: getPrefixLengthByDomain(
                    TON_DOMAIN_SIZE,
                    startsWithZeroByte,
                ),
                resolvedRecord: rootStorage.tonAddress.toNextResolver(),
            };
        }
    }

    val tMeDomain = beginCell()
        .storeSlice("me".literalSlice())
        .storeUint(0, BYTE_SIZE)
        .storeSlice("t".literalSlice())
        .storeUint(0, BYTE_SIZE)
        .toSlice();

    if (subdomainLengthInBits >= TELEGRAM_DOMAIN_SIZE * BYTE_SIZE) {
        if (subdomain.preloadBits(TELEGRAM_DOMAIN_SIZE * BYTE_SIZE).bitsEqual(tMeDomain)) {
            return {
                resolvedPrefixLengthBits: getPrefixLengthByDomain(
                    TELEGRAM_DOMAIN_SIZE,
                    startsWithZeroByte,
                ),
                resolvedRecord: rootStorage.tMeAddress.toNextResolver(),
            };
        }
    }

    return { resolvedPrefixLengthBits: 0, resolvedRecord: null };
}

import "errors"

const ONE_MONTH = 60 * 60 * 24 * 30
const ONE_YEAR = 60 * 60 * 24 * 366

const AUCTION_START_TIME = 1659171600 // GMT: Monday, 30 July 2022 г., 09:00:00
const AUCTION_START_DURATION = 60 * 60 * 24 * 7
const AUCTION_END_DURATION = 60 * 60
const AUCTION_PROLONGATION = 60 * 60

const MIN_TONS_FOR_STORAGE = ton("1")
const ONE_TON = ton("1")

// https://github.com/ton-blockchain/ton/blob/7e3df93ca2ab336716a230fceb1726d81bac0a06/crypto/block/block.tlb#L819
const DNS_NEXT_RESOLVER_PREFIX = 0xba93
const BYTE_SIZE = 8
const DNS_CONFIG_ID = 80

const TON_WWW_DOMAIN_SIZE = 8 // "ton.www" (6) + 2 null-encoding symbols
const TON_DOMAIN_SIZE = 4 // "ton" (3) + 1 null-encoding symbol
const TELEGRAM_DOMAIN_SIZE = 5 // "t.me" (3) + 2 null-encoding symbols
const MIN_DOMAIN_SIZE = 3
const MAX_DOMAIN_SIZE = 126

fun address.toNextResolver(self): cell {
    return beginCell().storeUint(DNS_NEXT_RESOLVER_PREFIX, 16).storeAddress(self).endCell();
}

// Snake-like domain in remaining bits/refs.
// "ab".ref("cd").ref("ef") -> "abcdef"
fun readDomainFromComment(mutate inMsgBody: slice): slice {
    var result = beginCell();

    result.storeSlice(inMsgBody.loadBits(inMsgBody.remainingBitsCount()));

    repeat (inMsgBody.depth()) {
        val refsLen = inMsgBody.remainingRefsCount();
        assert (refsLen == 1) throw ERROR_DOMAIN_FORMAT_INVALID;
        inMsgBody = inMsgBody.loadRef().beginParse();
        result.storeSlice(inMsgBody.loadBits(inMsgBody.remainingBitsCount()));
    }

    return result.toSlice();
}

// "ton\0test\0" -> "ton"
fun getTopDomainBits(domain: slice): int {
    var bytes = domain;

    var bits = 0;
    var shouldStop = false;

    while (!shouldStop) {
        // we do not check domain.length because it MUST contain \0 character
        val ch = bytes.loadUint(BYTE_SIZE);

        shouldStop = ch == 0;

        if (!shouldStop) {
            bits += BYTE_SIZE;
        }
    }

    // matches original FunC exit code
    assert (bits > 0) throw ERROR_DOMAIN_TOO_LONG;
    return bits;
}

enum DomainChar {
    Hyphen = 45      // ASCII '-': allowed only inside a label, not as the first/last checked char.
    DigitZero = 48   // ASCII '0': lower bound for allowed digits
    DigitNine = 57   // ASCII '9': upper bound for allowed digits
    LowercaseA = 97  // ASCII 'a': lower bound for allowed lowercase letters
    LowercaseZ = 122 // ASCII 'z': upper bound for allowed lowercase letters
}

@inline_ref
fun checkDomainString(domain: slice, len: int): bool {
    var bytes = domain;
    var i = 0;

    val charCount = len / BYTE_SIZE;
    val lastChar = charCount - 1;

    repeat (charCount) {
        val ch = bytes.loadUint(BYTE_SIZE);

        val isDigit = ch >= (DomainChar.DigitZero as int) && ch <= (DomainChar.DigitNine as int);
        val isLowercaseLetter = ch >= (DomainChar.LowercaseA as int) &&
        ch <= (DomainChar.LowercaseZ as int);

        var valid = isDigit || isLowercaseLetter;
        if (!valid) {
            valid = ch == (DomainChar.Hyphen as int) && i > 0 && i < lastChar;
        }

        if (!valid) {
            return false;
        }

        i += 1;
    }

    return true;
}

struct MinPriceConfig {
    startMinPrice: int
    endMinPrice: int
}

fun getMinPriceConfig(domainCharCount: int): MinPriceConfig {
    var res = MinPriceConfig {
        startMinPrice: 10,
        endMinPrice: 1,
    };

    if (domainCharCount == 4) {
        res = { startMinPrice: 1000, endMinPrice: 100 };
    }
    if (domainCharCount == 5) {
        res = { startMinPrice: 500, endMinPrice: 50 };
    }
    if (domainCharCount == 6) {
        res = { startMinPrice: 400, endMinPrice: 40 };
    }
    if (domainCharCount == 7) {
        res = { startMinPrice: 300, endMinPrice: 30 };
    }
    if (domainCharCount == 8) {
        res = { startMinPrice: 200, endMinPrice: 20 };
    }
    if (domainCharCount == 9) {
        res = { startMinPrice: 100, endMinPrice: 10 };
    }
    if (domainCharCount == 10) {
        res = { startMinPrice: 50, endMinPrice: 5 };
    }

    return res;
}

fun getMinPrice(domainBitsLength: int, nowTime: int): int {
    val config = getMinPriceConfig(domainBitsLength / BYTE_SIZE);
    var startMinPrice = config.startMinPrice * ONE_TON;
    val endMinPrice = config.endMinPrice * ONE_TON;

    val seconds = nowTime - AUCTION_START_TIME;
    val months = seconds / ONE_MONTH;

    var res: int;

    if (months > 21) {
        res = endMinPrice;
    } else {
        repeat (months) {
            // -10% each passing month
            startMinPrice = startMinPrice * 90 / 100;
        }

        res = startMinPrice;
    }

    return res;
}

import "dns-utils"
import "errors"

type DnsRecords = map<uint256, cell>

fun DnsRecords.packToBuilder(self, mutate b: builder) {
    b.storeUint(0, BYTE_SIZE);
    b.storeDict(self.toLowLevelDict());
}

fun DnsRecords.unpackFromSlice(mutate s: slice): DnsRecords {
    assert (s.loadUint(BYTE_SIZE) == 0) throw ERROR_CONTENT_TAG_INVALID;
    return createMapFromLowLevelDict<uint256, cell>(s.loadDict());
}

type DnsConfigMap = map<uint256, slice>

fun loadDnsConfigMap(configCell: cell): DnsConfigMap {
    var configSlice = configCell.beginParse();
    return createMapFromLowLevelDict(configSlice.loadDict());
}

struct CollectionStorage {
    content: cell
    nftItemCode: cell
}

struct CollectionDataReply {
    nextItemIndex: int
    content: cell
    ownerAddress: address?
}

fun CollectionStorage.load(): CollectionStorage {
    return CollectionStorage.fromCell(contract.getData());
}

struct RootDnsStorage {
    tonAddress: address
    tMeAddress: address
    tonWwwAddress: address
}

struct DnsResolveResponse {
    resolvedPrefixLengthBits: int
    resolvedRecord: cell?
}

struct ItemStorageNotInitialized {
    index: uint256
    collectionAddress: address
}

fun calcDeployedNftItem(index: uint256, itemCode: cell): AutoDeployAddress {
    val itemStorage = ItemStorageNotInitialized {
        index,
        collectionAddress: contract.getAddress(),
    };

    return { workchain: BASECHAIN, stateInit: { code: itemCode, data: itemStorage.toCell() } };
}

struct ItemStorageInitialized {
    index: uint256
    collectionAddress: address
    ownerAddress: address?
    content: Cell<DnsRecords>
    domain: cell
    auction: Cell<AuctionState>?
    lastFillUpTime: uint64
}

struct NftDataReply {
    isInitialized: bool
    index: uint256
    collectionAddress: address
    ownerAddress: address?
    content: Cell<DnsRecords>?
}

fun ItemStorageInitialized.save(self) {
    contract.setData(self.toCell());
}

fun ItemStorageInitialized.unpackAuction(self): (bool, AuctionState) {
    var res: (bool, AuctionState);

    if (self.auction == null) {
        res = (
            true,
            {
                auctionEndTime: 0,
                maxBidAmount: 0,
                maxBidAddress: null,
            },
        );
    } else {
        res = (false, self.auction.load());
    }

    return res;
}

struct ItemStorageMaybeNotInitialized {
    contractData: slice
}

fun startLoadingDnsItemStorage(): ItemStorageMaybeNotInitialized {
    return { contractData: contract.getData().beginParse() };
}

fun ItemStorageMaybeNotInitialized.isInitialized(self): bool {
    return self.contractData.remainingRefsCount() > 0;
}

fun ItemStorageMaybeNotInitialized.parseNotInitialized(self): ItemStorageNotInitialized {
    return ItemStorageNotInitialized.fromSlice(self.contractData);
}

fun ItemStorageMaybeNotInitialized.parseInitialized(self): ItemStorageInitialized {
    return ItemStorageInitialized.fromSlice(self.contractData);
}

struct AuctionState {
    maxBidAddress: address?
    maxBidAmount: coins
    auctionEndTime: uint64
}
